input.newString:
// Streams the upload straight to storage.
// The old in-memory Buffer.concat was a workaround for blobstore-sdk 1.x,
// which had no streaming write API (see commit d309e11). The SDK is now on
// 2.x, which provides putObjectStream(Readable) (see commit 7747b86), so we
// no longer need to hold the whole upload in memory.
async function upload(io, stream) {
  return io.putObjectStream(stream);
}

