input.command:
cd /workspace && node -e '
const { Readable } = require("stream");
const { upload } = require("./src/upload.js");

// Simulate a large upload; putObjectStream should receive the live Readable.
const payload = Buffer.alloc(8 * 1024 * 1024, 7);
const src = Readable.from([payload.subarray(0,4*1024*1024), payload.subarray(4*1024*1024)]);

const io = {
  putObjectStream(stream) {
    if (!(stream instanceof Readable)) throw new Error("expected a Readable");
    // Consume it like the SDK would, without buffering in upload().
    const received = [];
    return new Promise((resolve, reject) => {
      stream.on("data", (c) => received.push(c));
      stream.on("end", () => resolve(Buffer.concat(received)));
      stream.on("error", reject);
    });
  },
};

(async () => {
  const out = await upload(io, src);
  console.log("bytes received:", out.length, "matches input:", out.equals(payload));
})().catch((e) => { console.error("FAIL", e); process.exit(1); });
'

